use vstd::prelude::*;
use vstd::slice::*;

verus! {

spec fn is_odd(x: i32) -> bool {
    x % 2 != 0
}

spec fn all_even_up_to(a: &[i32], idx: int) -> bool {
    forall|i: int| 0 <= i < idx ==> !is_odd(a[i])
}

fn find_first_odd(a: &[i32]) -> (found: bool, index: usize)
    ensures
        // If not found, all elements are even
        !found ==> forall|i: int| 0 <= i < a.len() ==> !is_odd(a[i]),
        // If found:
        // 1. Index is within bounds
        // 2. Element at index is odd
        // 3. All elements before index are even
        found ==> (
            index < a.len(),
            is_odd(a[index]),
            all_even_up_to(a, index as int)
        ),
{
    let mut i: usize = 0;
    
    while i < a.len()
        invariant
            0 <= i <= a.len(),
            // All elements before current index are even
            all_even_up_to(a, i as int),
    {
        if is_odd(a[i]) {
            // Found the first odd element
            return (true, i);
        }
        
        // Current element is even, continue searching
        i = i + 1;
    }
    
    // Reached end without finding an odd element
    (false, 0)
}

}
